package org.dromara.sports.event.service;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import lombok.RequiredArgsConstructor;
import org.dromara.sports.platform.core.*;
import org.springframework.stereotype.Service;
import java.util.*;
import static org.dromara.sports.platform.core.BusinessSupport.*;
/** The existing event service remains the sole writer; page and agent actions use its validated transitions. */
@Service @RequiredArgsConstructor
public class EventActionProvider implements CapabilityProvider {
 private final EventPublicationService events;private final ScopedJdbc db;private final ObjectMapper json;
 private static final Set<String> READS=Set.of("asp_event","asp_event_command","asp_event_poster","asp_ai_task","asp_ai_task_file","asp_notification","asp_notification_delivery","asp_competition_unit","asp_competition_type","asp_fee_policy","asp_capacity_pool","asp_event_payment_config","asp_registration","asp_registration_member","asp_fee_obligation","asp_stage");
 private static final Set<String> WRITES=Set.of("asp_event","asp_event_command","asp_notification","asp_notification_delivery");
 public List<CapabilityDefinition> capabilities(){return List.of(cap("event.mine","查看我的赛事与发布检查",false,false,"eventId?"),cap("event.create","根据已核对材料建立赛事草稿",true,false,"draftJson"),cap("event.update","补充赛事草稿",true,false,"eventId","expectedVersion","draftJson"),cap("event.publish","核对项目费用和资料后发布赛事",true,true,"eventId","expectedVersion","contactName","contactMethod"));}
 private CapabilityDefinition cap(String c,String t,boolean write,boolean confirm,String...f){var definition=capability(json,c,t,"asp_event",true,confirm,Set.of("organizer"),"",READS,write?WRITES:Set.of(),f);if(definition.inputSchema().path("properties").has("draftJson"))((com.fasterxml.jackson.databind.node.ObjectNode)definition.inputSchema().path("properties").path("draftJson")).put("description","JSON对象文本：name、location、projectName、feeDescription、registrationOpensAt、registrationClosesAt、startsAt、endsAt（时间用含+08:00时区的ISO字符串），registrationReview=manual或none，rulesText、noticeText、declarationText、declarationAckRequired；材料不全须补问，人数与名额通过type.catalog核对后单独unit.create，收费通过fee.configure，最后本人确认event.publish。");return definition;}
 public JsonNode preview(String c,JsonNode in){if(!in.has("eventId"))return json.valueToTree(events.listManaged());long id=id(in,"eventId");var n=json.createObjectNode();n.set("event",json.valueToTree(events.managed(id)));n.set("readiness",json.valueToTree(events.readiness(id)));n.set("units",safeJson(json,db.list("SELECT u.id,u.name,u.competition_type_id,u.min_members,u.max_members,u.version,c.limit_count,f.revision AS fee_revision,f.amount,f.payment_mode,f.pay_instruction,f.qr_file_id FROM asp_competition_unit u LEFT JOIN asp_capacity_pool c ON c.unit_id=u.id LEFT JOIN asp_fee_policy f ON f.unit_id=u.id AND f.status='active' WHERE u.event_id=? ORDER BY u.id",id)));n.set("version",json.valueToTree(db.one("SELECT version FROM asp_event WHERE id=?",id).get("version")));return n;}
 public JsonNode execute(String c,JsonNode in){if(c.equals("event.mine"))return preview(c,in);if(c.equals("event.create")){var e=events.create(draft(in));return reference(json,"eventId",e.id(),"draft");}long id=id(in,"eventId");events.managed(id);var row=db.one("SELECT version FROM asp_event WHERE id=? FOR UPDATE",id);if(row==null||number(row.get("version"))!=in.path("expectedVersion").asLong(-1))throw fail("赛事已变化，请重新核对",409);if(c.equals("event.update")){events.update(id,draft(in));return reference(json,"eventId",id,"draft");}if(c.equals("event.publish")){events.publish(id,ActionContext.current().requestKey(),true,text(in,"contactName",100),text(in,"contactMethod",200));return reference(json,"eventId",id,"published");}throw fail("不支持的赛事办理",400);}
 private EventPublicationService.EventDraft draft(JsonNode in){try{var node=json.readTree(text(in,"draftJson",10000));if(!node.isObject())throw fail("请补充赛事资料",400);return json.treeToValue(node,EventPublicationService.EventDraft.class);}catch(org.dromara.common.core.exception.ServiceException e){throw e;}catch(Exception e){throw fail("赛事草稿格式无法识别，请继续补充或使用办赛表单",400);}}
}
